import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import { hasRoleAtLeast } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/** Admins, owners and platform staff see every private project. */
function seesAllPrivateProjects(actor: Actor): boolean {
  return actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin");
}

/**
 * Whether `actor` may see `project` at all. `org` and `public` projects are
 * visible org-wide; a `private` one only to admins/owners, platform staff,
 * its lead and its explicit project members. Always read live, so lead and
 * membership changes apply on the next call.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (seesAllPrivateProjects(actor)) return true;
  if (project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * A private project the actor may not see behaves as if it did not exist:
 * throws `NotFoundError` for `entity`/`id` (the project itself by default).
 */
export async function assertCanViewProject(
  actor: Actor,
  project: Project,
  entity = "Project",
  id: string = project.id,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

/** Same rule for an issue, judged by the project it belongs to. */
export async function assertCanViewIssue(
  actor: Actor,
  issue: Issue,
  entity = "Issue",
  id: string = issue.id,
): Promise<void> {
  const project = await projectRepo.findProjectById(
    issue.orgId,
    issue.projectId,
  );
  if (project === null) return;
  await assertCanViewProject(actor, project, entity, id);
}

/** Listing scope: unrestricted for privileged actors, else their own view. */
export function projectVisibilityScope(actor: Actor): ProjectVisibilityScope {
  return seesAllPrivateProjects(actor) ? {} : { visibleTo: actor.userId };
}
