import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("private", async () => {
  const t = await createTenant("privtmp", "growth");
  const { member, viewer, admin } = t.actors;
  const issue = await issueService.createIssue(member, issueInput(t.org.id, t.project.id));
  await commentService.createComment(member, { orgId: t.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] } as never);
  await projectRepo.updateProject({ orgId: t.org.id, projectId: t.project.id, visibility: "private" } as never);
  const p = (await projectRepo.findProjectById(t.org.id, t.project.id))!;
  expect(await projectService.canViewProject(member, p)).toBe(false);
  expect(await projectService.canViewProject(admin, p)).toBe(true);
  await expect(issueService.getIssue(viewer, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
  await expect(issueService.updateIssue(viewer, { orgId: t.org.id, issueId: issue.id, title: "x" } as never)).rejects.toBeInstanceOf(NotFoundError);
  await expect(commentService.getThread(member, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
  await expect(projectService.getProject(member, t.org.id, p.slug)).rejects.toBeInstanceOf(NotFoundError);
  const l = await projectService.listProjects(member, { orgId: t.org.id, limit: 10, cursor: null } as never);
  expect(l.total).toBe(0);
  const li = await issueService.listIssues(member, { orgId: t.org.id, limit: 10, cursor: null } as never);
  expect(li.total).toBe(0); expect(li.items.length).toBe(0);
  expect((await issueService.listIssues(admin, { orgId: t.org.id, limit: 10, cursor: null } as never)).total).toBe(1);
  await pm.addProjectMember(t.org.id, p.id, member.userId);
  expect((await projectService.listProjects(member, { orgId: t.org.id, limit: 10, cursor: null } as never)).total).toBe(1);
  expect((await issueService.listIssues(member, { orgId: t.org.id, limit: 10, cursor: null } as never)).total).toBe(1);
  await projectRepo.updateProject({ orgId: t.org.id, projectId: t.project.id, leadId: viewer.userId } as never);
  expect((await issueService.listIssues(viewer, { orgId: t.org.id, limit: 10, cursor: null } as never)).total).toBe(1);
  await issueService.getIssue(viewer, t.org.id, issue.id);
});
